const node=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;};
const car='<g class="story-auto"><path d="M120 237 146 185Q153 174 169 174h133q17 0 26 15l29 48 35 11q13 4 13 20v30H92v-32q0-18 14-23Z" fill="url(#body)" stroke="#9aaabc" stroke-width="2"/><path d="m154 188-23 45h207l-25-45Z" fill="#152739" stroke="#5d7185"/><path d="M234 185v49M103 264h36m220 0h32" stroke="#b5cadd" stroke-width="5"/><circle cx="153" cy="296" r="30" fill="#07111a" stroke="#647789" stroke-width="6"/><circle cx="348" cy="296" r="30" fill="#07111a" stroke="#647789" stroke-width="6"/><circle cx="153" cy="296" r="12" fill="#8396aa"/><circle cx="348" cy="296" r="12" fill="#8396aa"/><path d="M165 249h25m77 0h25" stroke="#e4ebf1" stroke-width="3"/></g>';
