const consignScenes=[
 illustration('Ilustración de revisión de datos y estado del vehículo',car+'<g class="story-document"><rect x="322" y="46" width="152" height="175" rx="15" fill="#101f2e" stroke="#576d80"/><path d="M348 78h95M372 112h65m-65 35h65m-65 35h65" stroke="#7e94a9" stroke-width="5"/><path d="m340 109 7 7 12-15m-19 43 7 7 12-15m-19 43 7 7 12-15" fill="none" stroke="#ff385b" stroke-width="4"/><circle cx="127" cy="110" r="33" fill="#ed003319" stroke="#ff385b"/><path d="m113 110 10 10 20-22" fill="none" stroke="#ff385b" stroke-width="4"/></g>'),
 illustration('Ilustración de acuerdo de consignación y entrega de llaves',car+'<g class="story-document"><rect x="52" y="45" width="178" height="139" rx="15" fill="#10202f" stroke="#60778c"/><path d="M78 77h124M78 99h99" stroke="#6e879e" stroke-width="5"/><path d="m83 147 22-22 10 21 29-17 18 17h34" fill="none" stroke="#f1f5f9" stroke-width="3"/><circle cx="371" cy="93" r="26" fill="none" stroke="#ff385b" stroke-width="9"/><path d="m389 113 47 47m-13-13 12-12m-24 0 12-12" stroke="#ff385b" stroke-width="9"/></g>'),
 illustration('Ilustración de fotografías y publicación del vehículo',car+'<g class="story-document"><path d="M63 175v-35h55m282 0h55v35M63 299v34h55m282 0h55v-34" stroke="#ff385b" stroke-width="4" fill="none"/><rect x="151" y="43" width="206" height="92" rx="14" fill="#10202f" stroke="#657d94"/><rect x="176" y="65" width="60" height="45" rx="7" fill="#233b50"/><circle cx="206" cy="87" r="14" fill="none" stroke="#ff385b" stroke-width="3"/><path d="M251 71h78m-78 18h59m-59 18h70" stroke="#738ba2" stroke-width="4"/></g>')];
const values=[['Claridad','Los detalles, a la vista.','Una ficha organizada ayuda a comparar fotos, características y precio antes de conversar.',illustration('Ilustración de una ficha de vehículo clara',car+'<rect x="310" y="45" width="160" height="170" rx="16" fill="#10202f" stroke="#60778c"/><path d="M333 78h108m-108 32h108m-108 32h70" stroke="#7890a6" stroke-width="5"/><rect x="333" y="170" width="104" height="22" rx="6" fill="#e90035"/>')],['Tu elección','Un camino que encaje contigo.','Tus planes y tu forma de usar el auto guían la conversación.',illustration('Ilustración de una ruta que conecta al conductor con su próximo vehículo','<path d="M37 315h60q53 0 53-85t65-85h79q60 0 60-76t125-36" stroke="#293f55" stroke-width="55" fill="none"/><path d="M37 315h60q53 0 53-85t65-85h79q60 0 60-76t125-36" stroke="#8da3b8" stroke-width="2" stroke-dasharray="9 10" fill="none"/><circle cx="55" cy="315" r="10" fill="#ff3657"/>'+car)],['Cercanía','Primero, conversemos.','Cuéntanos lo que buscas o lo que deseas vender. Prepara tu consulta sin complicaciones.',illustration('Ilustración de una conversación sobre un vehículo',car+'<path d="M46 46h192v93H102l-31 24v-24H46Z" fill="#10202f" stroke="#6e879d"/><path d="M278 75h180v80h-25v25l-30-25H278Z" fill="#ed00332a" stroke="#ff385b"/><path d="M73 77h136m-136 24h99M301 104h129m-129 22h94" stroke="#8ca1b6" stroke-width="5"/>')]];
export function enhanceStories(vehicles){
 const strip=document.querySelector('.brand-strip');strip.classList.add('expanded-brands');strip.replaceChildren();const intro=node('div','brands-heading');intro.append(node('span','eyebrow','MARCAS QUE MUEVEN TU PRÓXIMA HISTORIA'),node('p','','Explora el mundo automotor. Consulta las marcas y unidades disponibles en nuestro catálogo.'));const logos=node('div','brands-grid');const brands=[...new Set([...vehicles.filter(v=>!v.showcaseDemo&&!/^ferr?ari$/i.test(v.make)).map(v=>v.make),'Toyota','Ford','Nissan','Suzuki','Kia','Hyundai','Chevrolet','Volkswagen','Mitsubishi','Mazda','Honda','Changan','BYD','Jeep','BMW','Audi','Mercedes-Benz','Subaru'])];for(const make of brands){const tile=node('div','brand-logo'),img=node('img');img.src='/assets/brands/'+make.toLowerCase().replace(/\s/g,'-')+'.png';img.alt='Logo de '+make;img.loading='lazy';img.onerror=()=>{img.hidden=true;};tile.append(img,node('span','',make));logos.append(tile);}strip.append(intro,logos);
 const visual=document.querySelector('.consign-visual');visual.className='consign-visual story-consign';const artwork=node('div','story-art'),caption=node('div','story-caption'),label=node('span','eyebrow'),heading=node('strong'),description=node('p');caption.append(label,heading,description);visual.replaceChildren(artwork,caption);const descriptions=[['01 / CONOCER','Tu auto, con todos sus detalles.','Reunimos la información que permite presentar tu unidad: características, estado y fotografías.'],['02 / ACORDAR','Las condiciones, claras.','Conversamos sobre la propuesta de consignación y el siguiente paso.'],['03 / PRESENTAR','Una publicación que se entiende.','Fotos y datos organizados para que las personas conozcan tu vehículo.']];const setPhase=i=>{artwork.innerHTML=consignScenes[i];label.textContent=descriptions[i][0];heading.textContent=descriptions[i][1];description.textContent=descriptions[i][2];visual.dataset.phase=i;};setPhase(0);document.querySelectorAll('.steps li').forEach((li,i)=>{const h=li.querySelector('h3'),b=node('button','step-toggle',h.textContent);b.type='button';b.setAttribute('aria-pressed',String(i===0));h.replaceChildren(b);b.onclick=()=>{setPhase(i);document.querySelectorAll('.step-toggle').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));};});
 const scene=node('div','values-scene'),art=node('div','values-art'),copy=node('div','values-copy'),tabs=node('div','values-tabs'),title=node('strong'),text=node('p');tabs.setAttribute('role','group');tabs.setAttribute('aria-label','Conoce lo que nos mueve');copy.append(node('span','eyebrow','ASÍ QUEREMOS ACOMPAÑARTE'),title,text,tabs);scene.append(art,copy);values.forEach(([label,heading,description,svg],i)=>{const b=node('button','',label);b.type='button';b.setAttribute('aria-pressed',String(i===0));b.onclick=()=>{art.innerHTML=svg;title.textContent=heading;text.textContent=description;scene.dataset.value=i;tabs.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));};tabs.append(b);if(i===0){art.innerHTML=svg;title.textContent=heading;text.textContent=description;}});document.querySelector('#nosotros').append(scene);
 const contact=document.querySelector('#contacto'),form=contact.querySelector('form'),preview=node('div','contact-preview'),phone=node('div','message-window');phone.innerHTML='<div class="message-top"><img src="/assets/logo.png" alt=""><div>Tu consulta a Torres Garage<small>Vista previa · sin envío automático</small></div><span aria-hidden="true">✦</span></div><div class="message-preview-body"><span class="message-purpose"></span><p class="message-preview-text"></p><span class="message-ready"></span></div><div class="message-progress" aria-hidden="true"><i></i><i></i><i></i></div>';preview.append(phone);contact.firstElementChild.append(preview);const update=()=>{const name=form.elements.name.value.trim(),interest=form.elements.interest.value,message=form.elements.message.value.trim();phone.querySelector('.message-purpose').textContent=interest;phone.querySelector('.message-preview-text').textContent=(name?'Hola, soy '+name+'.\n\n':'Hola, Torres Garage.\n\n')+(message||'Escribe lo que tienes en mente. Tu consulta aparecerá aquí mientras la preparas.');const count=[!!name,!!interest,!!message].filter(Boolean).length;phone.querySelectorAll('.message-progress i').forEach((x,i)=>x.classList.toggle('complete',i<count));phone.querySelector('.message-ready').textContent=name&&message?'Lista para preparar y copiar':'Tu próximo paso empieza con una conversación';};document.addEventListener('click',event=>{if(event.target.closest('#sell-trigger,#inquire'))queueMicrotask(update);});form.addEventListener('input',update);form.addEventListener('change',update);contact.querySelector('h2').insertAdjacentHTML('afterend','<div class="contact-intents" role="group" aria-label="Motivo de la consulta"></div>');for(const [label,value]of [['Busco un auto','Quiero encontrar un vehículo'],['Quiero vender','Quiero vender mi vehículo'],['Tengo una pregunta','Quiero consultar por un modelo']]){const b=node('button','',label);b.type='button';b.onclick=()=>{form.elements.interest.value=value;update();form.elements.message.focus({preventScroll:true});};contact.querySelector('.contact-intents').append(b);}update();
 const observer=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('story-visible',e.isIntersecting)),{threshold:.15});for(const item of [visual,scene,preview])observer.observe(item);
}
